const items = $input.all();

const totalClientes = items.length;
const vip = items.filter(i => i.json.categoria_cliente === 'VIP').length;
const frecuentes = items.filter(i => i.json.categoria_cliente === 'frecuente').length;
const totalIngresos = items.reduce((sum, i) => sum + parseFloat(i.json.total_gastado), 0);

const filasHTML = items.map(i => `
    <tr>
        <td>${i.json.cliente}</td>
        <td>${i.json.total_compras}</td>
        <td>Q${parseFloat(i.json.total_gastado).toFixed(2)}</td>
        <td>${i.json.ultima_compra || '—'}</td>
        <td>${i.json.categoria_cliente}</td>
    </tr>
`).join('');

const telegramMsg = ` Reporte de clientes frecuentes

Total clientes: ${totalClientes}
VIP: ${vip}
Frecuentes: ${frecuentes}
Total ingresos: Q${totalIngresos.toFixed(2)}

Top clientes:
${items.slice(0,5).map(i =>
    `▪️ ${i.json.cliente} | ${i.json.total_compras} compras | Q${parseFloat(i.json.total_gastado).toFixed(2)}`
).join('\n')}`;

return [{
    json: {
        total_clientes: totalClientes,
        vip,
        frecuentes,
        total_ingresos: totalIngresos.toFixed(2),
        filas_html: filasHTML,
        telegram: telegramMsg
    }
}];
